sample:
# lesson01 ch01: はじめての Terraform
# この講座の「▶ 実行」は terraform init → apply → output を一気に実行します。
# terraform_data はクラウド不要の練習用リソースです。

resource "terraform_data" "hello" {
  input = "Hello, Terraform!"
}

# output は apply 後に値を表示するブロックです(採点にも使います)
output "message" {
  value = terraform_data.hello.output
}

output "tool" {
  value = "IaC"
}

exercise.answer:
# terraform_data は input に入れた値を output 属性としてそのまま持つ練習用リソースです。
# resource "型" "名前" { ... } が HCL の基本形で、参照は 型.名前.属性 と書きます。
resource "terraform_data" "greeting" {
  input = "Terraformをはじめます"
}

output "greeting" {
  value = terraform_data.greeting.output
}
